import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        new Main().runProgram();
    }

    private void runProgram() {
        InputReader in = new InputReader(System.in);
        PrintStream out = System.out;

        int n = in.nextInt();
        int k = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < k; i++) {
            base[in.nextInt()] = 1;
        }

        int[] current = new int[]{1};
        int exponent = n / 2;

        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                current = convolute(current, base, MOD);
            }
            base = convolute(base, base, MOD);
            exponent >>= 1;
        }

        long total = 0;
        for (int val : current) {
            total = (total + (long) val * val) % MOD;
        }
        out.println(total);
    }

    private int[] convolute(int[] x, int[] y, int mod) {
        int len = x.length + y.length - 1;
        int size = 1;
        while (size < len) size <<= 1;

        double[] xr = new double[size];
        double[] xi = new double[size];
        double[] yr = new double[size];
        double[] yi = new double[size];

        for (int i = 0; i < x.length; i++) {
            long val = x[i] % mod;
            if (val < 0) val += mod;
            xr[i] = val & 0x7fffL;
            xi[i] = val >> 15;
        }

        for (int i = 0; i < y.length; i++) {
            long val = y[i] % mod;
            if (val < 0) val += mod;
            yr[i] = val & 0x7fffL;
            yi[i] = val >> 15;
        }

        fft(xr, xi, false);
        fft(yr, yi, false);

        double[] resR = new double[size];
        double[] resI = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);
            double a1r = (xr[i] + xr[j]) * 0.5;
            double a1i = (xi[i] - xi[j]) * 0.5;
            double a2r = (xi[i] + xi[j]) * 0.5;
            double a2i = (xr[j] - xr[i]) * 0.5;

            double b1r = (yr[i] + yr[j]) * 0.5;
            double b1i = (yi[i] - yi[j]) * 0.5;
            double b2r = (yi[i] + yi[j]) * 0.5;
            double b2i = (yr[j] - yr[i]) * 0.5;

            resR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        }

        fft(resR, resI, true);

        int[] result = new int[len];
        for (int i = 0; i < len; i++) {
            long val = Math.round(resR[i]);
            long val2 = Math.round(resI[i]);
            long combined = (val + (val2 << 15)) % mod;
            result[i] = (int) combined;
        }
        return result;
    }

    private void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int bits = 31 - Integer.numberOfLeadingZeros(n - 1);
        for (int i = 1; i < n; i++) {
            int rev = Integer.reverse(i) >>> (32 - bits);
            if (i < rev) {
                double tmp = re[i]; re[i] = re[rev]; re[rev] = tmp;
                double tmp2 = im[i]; im[i] = im[rev]; im[rev] = tmp2;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            double wlenR = Math.cos(angle);
            double wlenI = Math.sin(angle);

            for (int i = 0; i < n; i += len) {
                double wR = 1, wI = 0;
                for (int j = 0; j < half; j++) {
                    double uR = re[i + j], uI = im[i + j];
                    double vR = re[i + j + half] * wR - im[i + j + half] * wI;
                    double vI = re[i + j + half] * wI + im[i + j + half] * wR;

                    re[i + j] = uR + vR;
                    im[i + j] = uI + vI;
                    re[i + j + half] = uR - vR;
                    im[i + j + half] = uI - vI;

                    double tmp = wR * wlenR - wI * wlenI;
                    wI = wR * wlenI + wI * wlenR;
                    wR = tmp;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] buf = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream input) {
            this.input = input;
        }

        private int next() {
            if (ptr >= len) {
                ptr = 0;
                try { len = input.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        public int nextInt() {
            int c = next();
            while (c <= 32) c = next();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = next();
            }
            int val = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new NumberFormatException();
                val = val * 10 + c - '0';
                c = next();
            }
            return val * sign;
        }
    }
}
